func newRunID() (string, error) {
	random := make([]byte, 10)
	if _, err := rand.Read(random); err != nil {
		return "", err
	}
	return fmt.Sprintf("%x-%s", time.Now().UTC().UnixMilli(), hex.EncodeToString(random)), nil
}
